def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if isinstance(value, datetime.timedelta):
        return value.total_seconds()
    else:
        raise ValueError('Expected a `timedelta` value, got {} instead.'.format(type(value)))

def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values."""
    if value.days != 0:
        return "%d:%d:%d:%d" % (value.days, value.seconds // 3600, (value.seconds // 60) % 60, value.seconds % 60)
    else:
        return "%d:%d:%d" % (value.seconds // 3600, (value.seconds // 60) % 60, value.seconds % 60)

