    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    handlers = cls._handlers()
    if protocol_version:
        if not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be a tuple")
        if protocol_version not in handlers:
            return {}
        return {protocol_version: handlers[protocol_version]}
    else:
        return handlers

def unit_of_work(metadata=None, timeout=None):
    def wrapper(func):
        @functools.wraps(func)
        def wrapped_func(tx):
            result = func(tx)
            if metadata:
                tx.metadata.update(metadata)
            if timeout:
                tx.timeout = timeout
            return result
        return wrapped_func
    return wrapper

def unit_of_work(metadata=None, timeout=None):
    def decorate(tx_func):
        def execute_func(tx, **kwargs):
            if timeout is not None and timeout >= 0:
                tx.configure(timeout=timeout)
            if metadata:
                tx.configure(metadata=metadata)
            return tx_func(tx, **kwargs)
        return execute_func
    return decorate

