def pop_u16(self):
    data = self.data
    if len(data) >= 2:
        return bytes([data.pop(-2), data.pop(-1)])
    else:
        raise ValueError("Insufficient data to pop")

def pop_u16(self):
        """ Remove the last two bytes of data, returning them as a big-endian
        16-bit unsigned integer.
        """

        if self.length < 2:
            raise IndexError("Cannot pop_u16, not enough bytes left in buffer!")
        self.length -= 2
        return bytes_to_u16(self.data[self.length:self.length + 2])

def discard(self, n=-1, qid=-1, dehydration_hooks=None, hydration_hooks=None, **handlers):
    self.extend([0x10, n, qid])
    if dehydration_hooks is not None:
        for type_, dehydrate_func in dehydration_hooks.items():
            self.extend([dehydrate_func(type_)])
    if hydration_hooks is not None:
        for type_, hydrate_func in hydration_hooks.items():
            self.extend([hydrate_func(type_)])
    for handler in handlers:
        self.extend([handler])
    return Response(self, handlers)

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None, db=None,
          imp_user=None, dehydration_hooks=None, hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """

    if mode not in ("READ", "WRITE", None):
        raise ValueError("Invalid mode '{}'".format(mode))

    properties = {}

    if mode:
        properties["mode"] = mode

    if bookmarks:
        properties["bookmarks"] = [
            [self._encode_structure(bookmark, None) for bookmark in bookmarks]
        ]

    if metadata:
        properties["metadata"] = [
            [self._encode_structure(metadata, None) for metadata in metadata]
        ]

    if timeout:
        properties["timeout"] = timeout

    if db:
        properties["database"] = db

    if imp_user:
        properties["imp_user"] = imp_user

    if dehydration_hooks:
        properties["dehydration_hooks"] = {
            key: self._encode_structure(value, None)
            for key, value in dehydration_hooks.items()
        }

    if hydration_hooks:
        properties["hydration_hooks"] = {
            key: self._encode_structure(value, None)
            for key, value in hydration_hooks.items()
        }

    if handlers:
        properties["handlers_declared"] = True

    return self._begin(properties, **handlers)

