def round_half_to_even(n):
    # Check if the number is a whole number
    if n % 1 == 0:
        return n

    # Round the number to the nearest even number
    rounded = round(n)
    if rounded % 2 == 0:
        return rounded
    else:
        return rounded - 1

def round_half_to_even(n):
    if n % 1 == 0.5:
        if int(n) % 2 == 0:
            return int(n)
        else:
            return int(n) + 1
    else:
        return round(n)

def point_type(name, fields, srid_map):
    class Point(object):
        def __init__(self, x, y, srid):
            self.x = x
            self.y = y
            self.srid = srid

    return Point

def point_type(name, fields, srid_map):
    # Create a new class with the given name and a superclass of `Point`
    cls = type(name, (Point,), {})

    # Add the `__srid_map__` attribute to the class
    cls.__srid_map__ = srid_map

    # Add an `__init__` method to the class that takes the same arguments as `Point`
    def __init__(x, y, z, srid=SRID.default):
        super().__init__(x, y, z, srid=srid)
        self.__dict__ = {
            'x': x,
            'y': y,
            'z': z,
            'srid': srid
        }

