def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    bases = set(classes)
    included = True
    while included:
        included = False
        for base in bases:
            if (issubclass(base, base.base) and base not in bases):
                bases.add(base.base)
                included = True
    return tuple(bases)

def minimalBases(classes):
    # Create a dictionary to keep track of the number of occurrences of each class
    class_counts = {}
    for cls in classes:
        if cls not in class_counts:
            class_counts[cls] = 1
        else:
            class_counts[cls] += 1

    # Sort the classes in descending order of their occurrence count
    sorted_classes = sorted(class_counts.items(), key=lambda x: x[1], reverse=True)

    # Create a new list to store the reduced bases
    reduced_bases = []

    # Iterate through the sorted classes and add them to the reduced bases list
    for cls, count in sorted_classes:
        reduced_bases.append(cls)
        # If the occurrence count is greater than 1, add the remaining classes as well
        if count > 1:
            for _ in range(count - 1):
                reduced_bases.append(cls)

    return reduced_bases

def minimalBases(classes):
    bases = list(classes)
    for i in range(len(bases)):
        for j in range(i, len(bases)):
            if issubclass(bases[i], bases[j]):
                bases[i:j] = []
                i = j - 1

    return tuple(bases)

