def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """

    if not sequence:
        return []

    if not output:
        output = []

    for arg in sequence:
        if isinstance(arg, (tuple, list)):
            _normalizeargs(arg, output)
        elif isinstance(arg, (Foliate.Declaration, _AbstractExternalDeclaration)):
            output.append(arg)
        else:
            output.extend(self._get_declarations_for(arg))

    return output

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    arity = len(sequence)
    ret = output if output is not None else []

    for i, arg in enumerate(sequence):
        if isinstance(arg, Declaration):
            ret.append(arg)
        elif isinstance(arg, tuple) and arity > 1:
            for sub_arg in arg:
                ret.append(sub_arg)
        elif arity == 1:
            ret.append(arg)
        else:
            raise ValueError(f"Invalid argument at position {i}: {arg}")

    return ret

def _normalizeargs(sequence, output=None):      
    """ Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or individual
    interfaces or implements specs.

    Anything but individial interfaces or implements specs will be expanded. """    
    if output is None:
        output = []

    for item in sequence:
        if isinstance(item, tuple):
            _normalizeargs(item, output)
        elif output not in (item, implements,):
            output.extend(item)

    return output

