    if len(weight) != self.dimension:
        raise ValueError("Invalid weight dimensions")

    # Replicate the histogram edge
    if coord[0] < 0 or coord[0] >= self.size[0]:
        return

    # Check if the coordinate already has a weight
    if coord in self.coords:
        # Update the weight value
        self.weights[coord] = self.weights[coord] + weight
    else:
        # Add a new coordinate and weight
        self.coords.append(coord)
        self.weights[coord] = weight

