    else:
        default_obs_dict = {field: None for field in manifest_dict}

    for key, value in manifest_dict.items():
        if isinstance(value, list):
            if len(value) == 0:
                default_obs_dict[key] = []
            else:
                # recurse into nested lists
                default_obs_dict[key] = [generate_default_observer_schema_dict(entry) for entry in value]
