    for schemanew_key, schemanew_val in enumerate(observer_schema):
        if schemanew_key not in last_applied_manifest:
            last_applied_manifest[schemanew_key] = []
        elif type(schemanew_val) == list:
            for resp_val in response:
                if resp_val not in last_applied_manifest[schemanew_key]:
                    last_applied_manifest[schemanew_key].append(resp_val)
    return last_applied_manifest

def update_last_applied_manifest(last_applied_manifest, observer_schema, response):
    for i, schema in enumerate(observer_schema):
        if schema.get("observer", None) == "list":
            if len(schema["fields"]) > last_applied_manifest[i]:
                last_applied_manifest[i] = len(schema["fields"])
                for field in response["fields"]:
                    if all(
                        field.get(attr, None) == observer_schema[field].get(attr, None)
                        for attr in ("observer", "field")
                    ):
                        update_last_applied_manifest(
                            field, observer_schema[field], response
                        )
        else:
            for field in response["fields"]:
                update_last_applied_manifest(field, observer_schema[field], response)

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    if not isinstance(last_applied_manifest, list):
        raise TypeError("Expected 'last_applied_manifest' to be of type list, but got " + str(type(list_last_applied_manifest)))
    if not isinstance(observer_schema, list):
        raise TypeError("Expected 'observer_schema' to be of type list, but got " + str(type(observer_schema)))
    if not isinstance(response, list):
        raise TypeError("Expected 'response' to be of type list, but got " + str(type(response)))
    for index, value in enumerate(response):
        if index >= len(last_applied_manifest):
            last_applied_manifest.append(value)
        else:
            last_applied_manifest.insert(index, value)
        update_last_applied_manifest_dict_from_resp(last_applied_manifest[index], observer_schema[index], response[index])
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this function is called recursively to update a partial ``last_applied_manifest`` from a partial Kubernetes response"""
    for observed_field in observer_schema:
        if observed_field not in response:
            raise KeyError(f"Observed field {observed_field} not present in response")
        if observed_field not in last_applied_manifest:
            last_applied_manifest[observed_field] = {}
        update_last_applied_manifest_dict_from_resp(last_applied_manifest[observed_field], observer_schema[observed_field], response[observed_field])

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for key, value in response.items():
        if key not in last_applied_manifest:
            last_applied_manifest[key] = value
        else:
            if type(value) == dict:
                last_applied_manifest[key] = update_last_applied_manifest_dict_from_resp(last_applied_manifest[key], observer_schema[key], value)
            elif type(value) == list:
                last_applied_manifest[key] = update_last_applied_manifest_list_from_resp(last_applied_manifest[key], observer_schema[key], value)
            else:
                continue
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for key in observer_schema.keys():
        if key not in last_applied_manifest:
            last_applied_manifest[key] = {}
        if isinstance(observer_schema[key], dict) and key in response:
            if len(observer_schema[key]) == 0:
                last_applied_manifest[key].update(response[key])
            else:
                update_last_applied_manifest_dict_from_resp(last_applied_manifest[key], observer_schema[key], response[key])
        elif key in response:
            last_applied_manifest[key] = response[key]
    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    import json
    from krake.helpers.observability import get_local_resource_names, get_local_resource_info
    from krake.data.kubernetes import (
        Deployment, ReplicaSet, DaemonSet, StatefulSet,
    )

    manifest = json.loads(app.spec.manifest)
    local_resource_names = get_local_resource_names(manifest)
    local_resource_info = get_local_resource_info(local_resource_names)

    for resource in local_resource_info:
        if "metadata" in resource:
            metadata = resource["metadata"]
        else:
            metadata = {}
        if "spec" in resource:
            spec_type = resource["spec"]["type"]
        else:
            spec_type = "Custom"

        name = metadata.get("name", "missing_name")
        namespace = metadata.get("namespace", "default")

        schema = {}
        if spec_type == "Deployment":
            schema = Deployment.get_default_observer_schema(name, namespace, **local_resource_info)
        elif spec_type == "ReplicaSet":
            schema = ReplicaSet.get_default_observer_schema(name, namespace, **local_resource_info)
        elif spec_type == "DaemonSet":
            schema = DaemonSet.get_default_observer_schema(name, namespace, **local_resource_info)
        elif spec_type == "StatefulSet":
            schema = StatefulSet.get_default_observer_schema(name, namespace, **local_resource_info)
        else:
            # TODO: handle any other resource types using the custom schema
            schema = {}

        yield (name, namespace), schema

    for name, namespace in local_resource_names:
        if name not in local_resource_info:
            yield (name, namespace), None

def generate_default_observer_schema(app):
    schema = {
