def format(self, sql, params):
    if isinstance(params, collections.abc.Mapping):
        in_style = "named"
        params = list(params.items())
    elif isinstance(params, collections.abc.Sequence):
        in_style = "ordinal"
    else:
        raise TypeError("Unsupported parameter type.")

    out_style = self.out_style

    if in_style == "named":
        # Convert named parameters to ordinal parameters
        params = {k: v for i, (k, v) in enumerate(params)}
        in_style = "ordinal"

    if not isinstance(sql, (str, bytes)):
        raise TypeError("sql must be a str or bytes object.")

    if out_style == "named":
        sql = re.sub(r"([?])([a-zA-Z0-9_]+)", r":\2", sql)
    elif out_style == "ordinal":
        sql = re.sub(r"([?])([a-zA-Z0-9_]+)", r"%d", sql)
    else:
        raise ValueError("Unsupported out-style parameter.")

    return sql, params

def formatmany(self, sql, many_params):
    # Step 1: Convert in-style parameters to out-style parameters
    out_params = []
    for params in many_params:
        # If params is a mapping (e.g. a dictionary), it means that in-style parameters are named
        if isinstance(params, Mapping):
            params = list(params.items())
        # If params is a sequence (e.g. a list), it means that in-style parameters are ordinal (e.g. '?')
        elif isinstance(params, Sequence):
            params = list(enumerate(params))
        else:
            raise ValueError("Invalid type for in-style parameters: {0}".format(type(params)))
        out_params.append(params)

    # Step 2: Format the SQL query
    sql = str(sql)
    for param_set in out_params:
        # If any of the out-style parameters is None, ignore it and skip to the next set
        if any(v is None for _, v in param_set):
            continue
        sql = sql.format(*[str(v) for _, v in param_set])

    return sql, out_params

def formatmany(self, sql, many_params):
    formatted_sql = sql
    converted_params = []
    for params in many_params:
        if isinstance(params, Mapping):
            formatted_sql = self._format_in_style_to_out_style(formatted_sql, params)
            converted_params.append(list(params.values()))
        elif isinstance(params, Sequence):
            formatted_sql = self._format_in_style_to_out_style(formatted_sql, params)
            converted_params.append(list(params))
        else:
            raise TypeError(f"Params must be a Mapping or Sequence, not {type(params)}")
    return formatted_sql, converted_params

