def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine the specification version. In the case that there is no type value or it isn't valid, then other tests will be based on the version given in self.spec_version.

    Arguments:
        inventory (Inventory): The inventory to validate
        extract_spec_version (bool, optional): Whether to extract the specification version from the inventory's type value. Defaults to False.

    Raises:
        ValueError: If the inventory is not valid
    """
    # Check if the inventory has a type value and that it is valid
    if extract_spec_version:
        if not inventory.type:
            raise ValueError("Inventory has no type value")
        try:
            self.spec_version = float(inventory.type)
        except ValueError:
            raise ValueError("Inventory has invalid type value")
    # Check if the version matches the inventory's type value if it exists
    if self.spec_version != inventory.type:
        raise ValueError("Inventory version does not match")
    # Check if the inventory has a name
    if not inventory.name:
        raise ValueError("Inventory has no name")
    # Check if the inventory has a vendor
    if not inventory.vendor:
        raise ValueError("Inventory has no vendor")
    # Check if the inventory has a model
    if not inventory.model:
        raise ValueError("Inventory has no model")
    # Check if the inventory has a revision
    if not inventory.revision:
        raise ValueError("Inventory has no revision")
    # Check if the inventory has at least one component
    if len(inventory.components) == 0:
        raise ValueError("Inventory has no components")

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if extract_spec_version:
        # Look for a valid type value
        if 'type' in inventory.keys():
            # Check if it conforms to the expected pattern
            if not re.match(r'^NS\d+_\w+_\d(\.\d+)?$', inventory['type']):
                raise ValueError("Invalid type value in inventory: {}".format(inventory['type']))
            # Extract the specification version from the type value
            spec_version = inventory['type'].split('_', 1)[1].split('_')[0] + '.e'
        else:
            # No type value found, fall back to the version specified in self.spec_version
            spec_version = self.spec_version
    else:
        # Use the version specified in self.spec_version without extracting from type value
        spec_version = self.spec_version

    # Validate the format and content of the inventory according to the specified specification version
    try:
        validate_inventory_format(inventory, spec_version)
        validate_inventory_content(inventory, spec_version)
    except ValueError as e:
        raise e

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """

    # Check that the inventory is a dictionary
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    # Check for required fields
    if "type" not in inventory:
        raise ValueError("Missing required field 'type' in inventory")
    if "specs" not in inventory:
        raise ValueError("Missing required field 'specs' in inventory")
    if "resources" not in inventory:
        raise ValueError("Missing required field 'resources' in inventory")

    # Extract the spec version if needed
    if extract_spec_version:
        spec_version = inventory.get("type", None)
        if spec_version is None:
            raise ValueError("Inventory is missing the 'type' field, which is required to determine the specification version")
        spec_version = spec_version.split(".")[-1]
        inventory["specs"] = inventory["specs"][spec_version]
        if not isinstance(inventory["specs"], dict):
            raise ValueError("Inventory 'specs' field for spec version '{}' is not a dictionary".format(spec_version))

    # Validate the 'specs' field
    if not isinstance(inventory["specs"], dict):
        raise ValueError("Inventory 'specs' field is not a dictionary")
    for spec_name, spec in inventory["specs"].items():
        if not isinstance(spec, dict):
            raise ValueError("Inventory 'specs' field value for '{}' is not a dictionary".format(spec_name))
        if "type" not in spec:
            raise ValueError("Missing required field 'type' in inventory 'spec' field value for '{}'".format(spec_name))
        if "scripts" not in spec:
            raise ValueError("Missing required field 'scripts' in inventory 'spec' field value for '{}'".format(spec_name))
        if "values" not in spec:
            raise ValueError("Missing required field 'values' in inventory 'spec' field value for '{}'".format(spec_name))
        for script in spec["scripts"]:
            validate_script(script)
        for value in spec["values"]:
            validate_value(value)

    # Validate the 'resources' field
    for resource_name, resource in inventory["resources"].items():
        if not isinstance(resource, dict):
            raise ValueError("Inventory 'resources' field value for '{}' is not a dictionary".format(resource_name))
        if "type" not in resource:
            raise ValueError("Missing required field 'type' in inventory 'resource' field value for '{}'".format(resource_name))
        if "method" not in resource:
            raise ValueError("Missing required field 'method' in inventory 'resource' field value for '{}'".format(resource_name))
        if "statements" not in resource:
            raise ValueError("Missing required field 'statements' in inventory 'resource' field value for '{}'".format(resource_name))
            if not isinstance(resource["statements"], list):
                raise ValueError("Inventory 'statements' field value is not a list for '{}'".format(resource_name))

    # Return the validated inventory
    return inventory

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """

    # Ensure inventory is a 1D array
    if not isinstance(inventory, np.ndarray) or len(inventory.shape) != 1:
        raise TypeError(f"Inventory must be a 1D np.ndarray.")

    # Ensure inventory contains valid entries
    for entry in inventory:
        if not isinstance(entry, (InventoryEntry, str)) or (isinstance(entry, str) and not re.match(r"^<(<.*>)?$", entry)):
            raise ValueError(f"Inventory must consist of InventoryEntry objects or valid XML representation as strings.")

    # Extract specification version
    if extract_spec_version:
        try:
            spec_version = entry_to_inventory_element(entry).attrib['type']
        except KeyError:
            spec_version = self.spec_version

    # Check that specification version is valid
    if not re.match(r"<[1-9][0-9]*\.[1-9][0-9]*\.[1-9][0-9]*", spec_version):
        raise ValueError(f"Specification version {spec_version} is not valid.")

    # Validate each inventory entry
    for entry in inventory:
        if isinstance(entry, InventoryEntry):
            entry.validate(self, spec_version)
        else:
            if not re.match(r"^<(<.*>)?$", entry):
                raise ValueError(f"Inventory entry {entry} is not a valid XML representation.")

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Create a set of all digests in the manifest
    digests_all = {x.split(' ')[0] for x in manifest_files if x.startswith('DIGESTS : ')}
    # Check if all needed digests are present in the manifest
    digests_needed = set(digests_used) | set(self.get_missing_digests())
    if digests_needed - digests_all:
        raise ValueError('The following digests are needed but not present in the manifest: {}'.format(digests_needed - digests_all))
    # Check if all used digests are present in the manifest
    digests_used = digests_used - self.get_missing_digests()
    if digests_used - digests_all:
        raise ValueError('The following digests are used but not present in the manifest: {}'.format(digests_used - digests_all))
    return digests_needed

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Check if the manifest file is a CSV file
    if not manifest_files.endswith(".csv"):
        raise ValueError("The manifest file is not a CSV file.")

    # Load the manifest file as a dataframe
    manifest = pd.read_csv(manifest_files)

    # Check if the digest column is present in the manifest file
    if "digest" not in manifest.columns:
        raise ValueError("The manifest file does not contain a 'digest' column.")

    # Check if all required digests are present in the manifest file
    for digest in digests_used:
        if digest not in manifest["digest"].values:
            raise ValueError(f"The digest '{digest}' is missing from the manifest file.")

    # Check if all required digests are used in the manifest file
    used_digests = set(manifest["digest"].values)
    if len(used_digests) != len(digests_used):
        raise ValueError("Not all required digests are used in the manifest file.")

    # Check if the digest values are correct
    for i, row in manifest.iterrows():
        if row["digest"] not in digests_used:
            raise ValueError(f"The digest value '{row['digest']}' in row {i+1} is not a valid digest.")

