def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Check if prior and self have the same class
        if self.__class__ != prior.__class__:
            raise TypeError("Input prior is not the same class as self")

        # Check if prior and self have the same audit trail
        if self.audit_trail != prior.audit_trail:
            raise ValueError("Input prior does not have the same audit trail as self")

        # Check if prior and self have the same parent
        if self.parent != prior.parent:
            raise ValueError("Input prior does not have the same parent as self")

        # Check if prior and self have the same child elements
        if self.children != prior.children:
            raise ValueError("Input prior does not have the same child elements as self")

        # Check if prior and self have the same attributes
        if self.attributes != prior.attributes:
            raise ValueError("Input prior does not have the same attributes as self")

        # Check if prior and self have the same text content
        if self.text_content != prior.text_content:
            raise ValueError("Input prior does not have the same text content as self")

        # Check if prior and self have the same scope
        if self.scope != prior.scope:
            raise ValueError("Input prior does not have the same scope as self")

        # Check if prior and self have the same inverted index
        if self.inverted_index != prior.inverted_index:
            raise ValueError("Input prior does not have the same inverted index as self")

        # Check if prior and self have the same relations
        # Recursively check all children and attributes
        if len(self.relations) != len(prior.relations):
            raise ValueError("Input prior does not have the same number of relations as self")
        else:
            for rel in self.relations:
                for child in rel.children:
                    if child not in prior.relations:
                        raise ValueError("Input prior does not have the same children in one of the relations")
                    if child. relativeship_type != rel.type:
                        raise ValueError("Input prior does not have the same children in one of the relations")
                    if rel.conditions != rel.conditions:
                        raise ValueError("Input prior does not have the same conditions in one of the relations")

        # Everything has been checked, the input prior is a valid prior version
        return True

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if not isinstance(prior, InventoryValidator):
            raise ValueError("prior is not a valid InventoryValidator object")

        if self.item_num != prior.num_items + 1:
            raise ValueError("self.item_num is not equal to prior.num_items + 1")

        if self.version_id != prior.current_version_id + 1:
            raise ValueError("self.version_id is not equal to prior.current_version_id + 1")

        if not self.items.issuperset(prior.items):
