def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """

    # Check that prior is a valid InventoryValidator object
    if not isinstance(prior, InventoryValidator):
        raise TypeError(f"Expected an InventoryValidator object but got {type(prior)} instead")

    # Check that both inventories have the same ID
    if self.id != prior.id:
        raise ValueError(f"Inventory ids do not match: '{self.id}' vs '{prior.id}'")

    # Check that both inventories are version 1.0
    if self.version != "1.0" or prior.version != "1.0":
        raise ValueError(f"Inventory version is not 1.0: '{self.version}' vs '{prior.version}'")

    # Check that all prior records are present in the current inventory
    for prior_record in prior.records:
        if not self.has_record(prior_record):
            raise ValueError(f"Previous record not found in current inventory: '{prior_record}'")

    # Check that all current records are present in the prior inventory
    for current_record in self.records:
        if not prior.has_record(current_record):
            raise ValueError(f"Record not found in previous inventory: '{current_record}'")

    # Check that all prior pending updates are present in the current inventory
    for prior_pending_update in prior.pending_updates:
        if not self.has_pending_update(prior_pending_update):
            raise ValueError(f"Previous pending update not found in current inventory: '{prior_pending_update}'")

    # Check that all current pending updates are present in the prior inventory
    for current_pending_update in self.pending_updates:
        if not prior.has_pending_update(current_pending_update):
            raise ValueError(f"Pending update not found in previous inventory: '{current_pending_update}'")

    # Check that all prior rejected updates are present in the current inventory
    for prior_rejected_update in prior.rejected_updates:
        if not self.has_rejected_update(prior_rejected_update):
            raise ValueError(f"Previous rejected update not found in current inventory: '{prior_rejected_update}'")

    # Check that all current rejected updates are present in the prior inventory
    for current_rejected_update in self.rejected_updates:
        if not prior.has_rejected_update(current_rejected_update):
            raise ValueError(f"Rejected update not found in previous inventory: '{current_rejected_update}'")

