def _extract_number_and_supplment_from_issue_element(issue):
    # extract the content of the issue element
    issue_content = issue.text
    # remove all whitespaces from the content
    issue_content = issue_content.replace(" ", "")
    # check if the content is empty or not
    if not issue_content:
        raise ValueError("Issue element is empty")
    # check if the content contains either "suppl" or "spe"
    if "suppl" in issue_content or "spe" in issue_content:
        # extract the number and supplement number
        number = issue_content.split(" ")[0]
        suppl = issue_content.split(" ")[1]
        # return a tuple containing the number and supplement number
        return (number, suppl)
    else:
        # return just the number
        return (issue_content)

def extract_number_and_suppl_from_issue_element(issue):
    """
    Extract the "number" and "suppl" values from the issue element.
    """
    number = None
    suppl = None
    text = issue.text
    matches = re.findall(r"(\d+)\s?(spe|suppl|suppl\s\d|suppl.\d)?\s?(\d*)", text)
    if matches:
        for match in matches:
            number = match[0]
            suppl = match[1]
            break
    if not suppl:
        suppl = "1"
    return (number, suppl)

def _extract_number_and_supplment_from_issue_element(issue):
    number = None
    suppl = None
    issue_text = issue.text_content()
    match = re.search(r'(\d+)( Suppl (\d+)|\bSuppl\.?\s*(\d+)|\bSuppl\.?)\.?', issue_text)
    if match:
        number = match.group(1)
        if match.group(3):
            suppl = match.group(3)
        else:
            suppl = match.group(4)
    return number, suppl

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    if not hasattr(self, "text"):
        raise ValueError("Object has no property named 'text'.")
    if not isinstance(self.text, str):
        raise ValueError("Object.text property must be a string value.")
    if not hasattr(self, "type"):
        raise ValueError("Object has no property named 'type'.")
    if not isinstance(self.type, str):
        raise ValueError("Object.type property must be a string value.")
    if indent < 0:
        raise ValueError("Indent cannot be negative.")

    s = " " * indent
    s += self.type + ": "
    s += self.text

    if debug:
        if hasattr(self, "id"):
            s += "\n" + " " * (indent + 1) + "id: " + str(self.id)
        if hasattr(self, "metadata"):
            for k, v in self.metadata.items():
                s += "\n" + " " * (indent + 1) + k + ": " + str(v)

    return s

