def absorb(self, args):
    result = []
    for arg in args:
        if isinstance(arg, Expression) and arg.operator in [AND, OR]:
            for inner_expr in arg.terms:
                if isinstance(inner_expr, Expression) and inner_expr.operator == NOT and inner_expr.terms[0] == arg:
                    result.append(inner_expr.terms[0])
                elif isinstance(inner_expr, Expression) and inner_expr.operator == NOT and inner_expr.terms[0] in result:
                    result.remove(inner_expr.terms[0])
                elif not isinstance(inner_expr, Expression):
                    if inner_expr not in result:
                        result.append(inner_expr)
                elif inner_expr in result:
                    result.remove(inner_expr)

    return result

def absorb(self, args):
