    for arg in args:
        if arg.op == '&' or arg.op == '|':
            other_arg = arg.args[0] if arg.args[0] != self else arg.args[1]
            if other_arg.op == '~':
                other_arg = other_arg.args[0]
            if arg.op == '&':
                if other_arg.op == '~':
                    new_args.append(arg.args[0] & other_arg.args[0])
                else:
                    new_args.append(arg.args[0])
            else:
                if other_arg.op == '~':
                    new_args.append(arg.args[0] | other_arg.args[0])
                else:
                    new_args.append(arg.args[0])
        else:
            new_args.append(arg)
    return new_args

