def normalized(self):
    relativedelta_ints = relativedelta()
    for attr in ['days', 'months', 'years']:
        if hasattr(self, attr):
            value = getattr(self, attr)
            int_value = int(value)
            setattr(relativedelta_ints, attr, int_value)
    return relativedelta_ints

def normalized(self):
    difference = relativedelta(self)
    result = relativedelta()
    for attr, value in difference.items():
        if isinstance(value, int):
            result[attr] = value
        elif isinstance(value, float):
            result[attr] = round(value)
        else:
            raise ValueError(f"Invalid value type: {value}")
    return result

def normalized(self):
    new_self = self.__class__()
    for field, value in self.__dict__.items():
        if isinstance(value, float):
            new_self.__dict__[field] = round(value)
        else:
            new_self.__dict__[field] = value
    return new_self

