def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Check if the commands are valid
    if not commands:
        raise ValueError("No command(s) were provided.")
    # Check if the arguments are valid
    if not args:
        raise ValueError("No argument(s) were provided.")
    # Check if the working directory is valid
    if not cwd:
        raise ValueError("No working directory was provided.")
    # Check if the environment is valid
    if not env:
        raise ValueError("No environment was provided.")

    # Run the command
    result = subprocess.run([commands, *args], cwd=cwd, capture_output=True, text=True, check=True)

    # Check if the stderr should be hidden
    if hide_stderr:
        # Hide the stderr
        result.stderr = None

    # Check if the output should be verbose
    if verbose:
        # Print the stdout and stderr
        print(result.stdout)
        print(result.stderr)

    return result.stdout.rstrip()

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s).

    Arguments:
        commands (str or list[str]): The command(s) to run
        args (list[str or tuple[str, str]]): The arguments to pass to the command(s)
        cwd (str): The directory to run the command(s) in
        verbose (bool): Print the command(s) and their output to stdout
        hide_stderr (bool): Redirect stderr to stdout during the execution of the command
        env (dict): Environment variables to set when running the command(s)
    """
    import subprocess
    import shlex

    if isinstance(commands, str):
        commands = [commands]

    if not isinstance(commands, list):
        raise TypeError("commands must be a string or a list of strings")

    for command in commands:
        if shlex.split(command)[0] not in ["start", "stop", "restart"]:
            raise ValueError("Invalid command: '" + command + "'")

    for arg in args:
        if not isinstance(arg, str):
            raise TypeError("args must be a list of strings")

    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string or None")

    if verbose and not isinstance(verbose, bool):
        raise TypeError("verbose must be a boolean")

    if hide_stderr and not isinstance(hide_stderr, bool):
        raise TypeError("hide_stderr must be a boolean")

    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dict or None")

    process = None

    for command in commands:
        process = subprocess.run(shlex.split(command) + args, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE if hide_stderr else None, env=env)

    if verbose:
        print(commands[0] + " " + " ".join(args) + " > " + process.stdout.decode("utf-8"))
        if process.stderr:
            print(commands[0] + " " + " ".join(args) + " > " + process.stderr.decode("utf-8"))

    return process

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    process = subprocess.Popen(
        commands,
        args,
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE if hide_stderr else None,
        env=env,
        universal_newlines=True
    )

    if verbose:
        for line in process.stdout:
            print(line.rstrip())

    stdout_code = process.returncode
    if hide_stderr:
        stderr_code = ''
    else:
        stderr_code = ''
        for line in process.stderr:
            print(line.rstrip(), file=sys.stderr)

    return stdout_code, stderr_code

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        commands = [commands]
    if not isinstance(args, list):
        args = [args]

    cmdline = [c + a for c, a in zip_longest(commands, args, fillvalue='')]
    if cwd:
        cmdline = 'cd {0} && {1}'.format(cwd, cmdline)

    if verbose:
        print(cmdline)

    cmd = subprocess.Popen(cmdline, shell=True, stderr=subprocess.PIPE if hide_stderr else None, env=env)

    # wait for the command to finish
    retcode = cmd.wait()
    stdout, stderr = cmd.communicate()

    if retcode != 0:
        raise subprocess.CalledProcessError(retcode, cmdline, output=stdout, stderr=stderr)

    return stdout

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    def _wrapper(func):
        if not callable(func):
            raise ValueError("register_vcs_handler must be called with a method as its first argument")
        func.vc_handler = True
        if not hasattr(func, '__vc_handlers__'):
            func.__vc_handlers__ = []
        func.__vc_handlers__.append(vcs)
        return func
    return _wrapper

def register_vcs_handler(vcs, method):
    def decorator(func):
        # Check if the VCS exists
        if not vcs in VCS_LIST:
            raise ValueError("Invalid VCS specified: " + str(vcs))
        # Check if the method exists in the VCS dictionary
        if not method in VCS_LIST[vcs]:
            raise ValueError("Invalid method for VCS: " + method)
        # Add the method to the VCS dictionary
        VCS_LIST[vcs][method] = func
        return func
    return decorator

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""

    def decorator(func):
        """Provide the decorator function."""
        if not callable(func):
            raise TypeError("'register_vcs_handler' requires a callable.")
        vcs.set_handler(func)
        return method

    return decorator

def handler(self, event):
        """Handler for a VCS event."""
        # Check if the event is the correct type
        if not isinstance(event, vcs.Event):
            raise ValueError("Expected {} event, got {}".format(vcs.Event, type(event)))
        # Run the decorated method
        return method(self, event)
    return handler

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0

    # Iterate over all elements in the storage root
    for element in self:
        num_objects += 1

        # If validation of objects is requested, check if the element is a valid object
        if validate_objects and isinstance(element, AbstractObject):
            if not isinstance(element, (int, float, str, bool)):
                if not element.id:
                    if show_warnings:
                        print(f"WARNING: Object {element} has no id.")
                if not element.schema:
                    if show_warnings:
                        print(f"WARNING: Object {element} has no schema.")
                if not element.digest or not element.digest.endswith("."):
                    if show_warnings:
                        print(f"WARNING: Object {element} has an invalid digest.")
            else:
                good_objects += 1

    # If validation of digests is requested, check if the element's digest is valid
    if validate_objects and check_digests:
        for digest in self._storage.keys():
            try:
                element = self._storage[digest]
                if not isinstance(element, AbstractObject):
                    continue
                if not element.id:
                    if show_warnings:
                        print(f"WARNING: Object {element} has no id.")
                if not element.schema:
                    if show_warnings:
                        print(f"WARNING: Object {element} has no schema.")
                if not element.digest or not element.digest.endswith("."):
                    if show_warnings:
                        print(f"WARNING: Object {element} has an invalid digest.")
            except KeyError:
                pass

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0
    for e in self:
        # verify that all elements in the hierarchy have a valid ID
        if e.id is None or not isinstance(e.id, str):
            if show_warnings:
                print(f"Warning: element {e} has invalid ID {e.id}")
            continue
        # verify that all elements in the hierarchy are instances of classes in the expected list of class IDs
        if not e.cls in list_of_valid_class_IDs:
            if show_warnings:
                print(f"Warning: element {e} has invalid class ID {e.cls}")
            continue
        num_objects += 1
        if not validate_objects:
            continue
        # verify that all objects in the hierarchy have valid digests
        if check_digests and not e.validate_digest():
            if show_warnings:
                print(f"Warning: element {e} has invalid digest")
            continue
        good_objects += 1
    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0

    for root_item in self.root_items:
        for item in root_item.walk():
            num_objects += 1
            if validate_objects and not hasattr(item, "validate_object"):
                if show_warnings:
                    warnings.warn(f"Object {item} of type {type(item)} does not have the `validate_object` method defined", RuntimeWarning)
            else:
                if not item.validate_object(check_digests):
                    print(f"Object {item} of type {type(item)} failed validation")
                else:
                    good_objects += 1

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern."""

    if "v" in version:
        version = version[1:]

    major, minor, patch = version.split(".")
    patch = str(int(patch) + 1)

    if int(patch) == 100:
        minor = str(int(minor) + 1)
        patch = "00"

    if int(minor) == 100:
        major = str(int(major) + 1)
        minor = "00"

    if int(major) == 10:
        version = "v" + str(major) + ".00.00"
    else:
        version = "v" + str(major) + "." + str(minor) + "." + str(patch)

    return version

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    major, rest = version.split('.')
    if rest.startswith('0'):
        minor = rest.strip('0')
    else:
        minor = '0'
    return f'{major}.{minor}'

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version[-1].isdigit():
        return str(int(version[-1]) + 1)
    else:
        return str( chr(ord(version[-1]) + 1) )

def next_version(version):
    match = re.match(r'^(\d+)\.(\d+)$', version)
    if not match:
        raise InvalidVersionError(f"Invalid version format: {version}")
    major, minor = match.groups()
    major, minor = int(major), int(minor)
    if minor == 99:
        return f"{major + 1}.0"
    else:
        return f"{major}.{minor + 1}"

    raise InvalidVersionError("Invalid version format")

def validate_version_inventories(self, version_dirs):
    for version in version_dirs:
        inventory_path = os.path.join(self.root_dir, version, "inventory.json")
        if not os.path.exists(inventory_path):
            raise InvalidInventoryError(f"Missing inventory for version {version}, file not found: {inventory_path}")
        with open(inventory_path, "r") as f:
            inventory = json.load(f)
            digest = compute_content_digest(inventory)
            if digest != self.root_digest:
                self.content_digests[version] = digest
    for version in self.content_digests:
        if version not in version_dirs:
            raise InvalidInventoryError(f"Version {version} has no inventory, but there is a content digest record.")

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        inventory_paths = []
        content_digests = {}

        for version_dir in version_dirs:
            inventory_path = os.path.join(version_dir, INVENTORY_FILENAME)
            if not os.path.isfile(inventory_path):
                raise ValueError(f"Missing inventory file {inventory_path} for version dir {version_dir}")
            inventory_paths.append(inventory_path)

        for inventory_path in inventory_paths:
            with open(inventory_path, "r") as inventory_file:
                inventory = json.load(inventory_file)
            for content_path, content_digest in inventory.items():
                if content_path in content_digests:
                    if content_digests[content_path] != content_digest:
                        raise ValueError(f"Different digest for content {content_path} in version {version_dir}")
                content_digests[content_path] = content_digest

        return content_digests

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        # Validate that each version directory has an inventory file
        for version_dir in version_dirs:
            inventory_path = os.path.join(version_dir, "inventory.csv")
            if not os.path.isfile(inventory_path):
                raise FileNotFoundError(f"Inventory file {inventory_path} not found")
        # Keep a record of any content digests different from those in the root inventory
        root_inventory = self.read_inventory(self.root_dir)
        root_digests = set(root_inventory["digest"])
        for version_dir in version_dirs:
            inventory = self.read_inventory(version_dir)
            for digest in inventory["digest"]:
                if digest not in root_digests:
                    self.versions[version_dir]["digests"].add(digest)
        # Validate that every version has a unique content digest
        for version_dir, version_data in self.versions.items():
            if len(version_data["digests"]) > 1:
                raise ValueError(f"Version {version_dir} has multiple content digests: {version_data['digests']}")

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if not os.path.isdir(path):
        return "other"
    elif os.path.basename(path) == "0=*":
        with open(os.path.join(path, ocflib.NAMASTE)) as f:
            namaste = f.read()
        if namaste.startswith("[OCFL Storage Root]"):
            return "root"
        elif namaste.startswith("[OCFL Object]"):
            return "object"
        else:
            return "other"
    else:
        return "other"

    if not os.path.isfile(os.path.join(path, ocflib.INVENTORY)):
        return "file"
    else:
        return "inventory"

def find_path_type(path):
    # Check if the path exists and is a directory
    if not os.path.exists(path) or not os.path.isdir(path):
        return "not_found"

    # Check if the path looks like an OCFL Storage Root
    if os.path.join(path, "headers") == os.path.exists(path, "headers"):
        return "root"

    # Check if the path looks like an OCFL Object
    if os.path.join(path, "config.yml") == os.path.exists(path, "config.yml") and os.path.join(path, "data") == os.path.exists(path, "data"):
        return "object"

    # Check if the path looks like a file
    if os.path.isfile(path):
        return "file"

    # If none of the above conditions are met, the path does not correspond to any possible inventory server root
    return "not_found"

def find_path_type(path):
    if path == "0=*":
        return "root"
    elif path.startswith("0=*/"):
        return "object"
    elif path.endswith(".txt"):
        return "file"
    else:
        # If the file is not a well-known type, return a string that explains the error
        return "Unknown file type at path: " + path

def find_path_type(path):
    path = Path(path)
    if path.is_dir():
        return "directory"
    elif path.is_file():
        if path.name == "0=*" and path.exists():
            return "root"
        elif path.name.endswith(".ocf"):
            return "object"
        elif path.name.endswith(".txt") and path.read_text().startswith("INVENTORY"):
            return "inventory"
        else:
            return "other"
    else:
        return "other"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""

    if not bug_ids:
        raise ValueError("No bug IDs specified")

    # Create a new list to store the amended params
    new_params = []
    for param in params:
        # Check if the param is for a bug ID in the list
        if param.startswith("bug_"):
            bug_id = param[4:]
            if bug_id in bug_ids:
                # Add the param to the list
                new_params.append(param)
        else:
            # If the param is not for a bug ID, add it to the list as-is
            new_params.append(param)

    return new_params

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Check if the params argument is a dict
    if not isinstance(params, dict):
        raise TypeError("The 'params' argument must be a dict")

    # Check if the bug_ids argument is a list
    if not isinstance(bug_ids, list):
        raise TypeError("The 'bug_ids' argument must be a list")

    # A dictionary to store the results
    results = {}

    # Iterate over the bug_ids and append the corresponding param values to the results dictionary
    for bug_id in bug_ids:
        if bug_id in params:
            results[bug_id] = params[bug_id]

    # Return the results dictionary
    return results

def deep_merge_nodes(nodes):
    merged_nodes = {}
    for node in nodes:
        key = node[0].value
        value = node[1]
        if key not in merged_nodes:
            merged_nodes[key] = value
        else:
            # if the key is already present in the merged nodes dict,
            # deep merge the new value with the existing value
            merged_nodes[key] = deep_merge_nodes(merged_nodes[key], value)
    return merged_nodes

def deep_merge_nodes(nodes):
      nodes_dict = {}
      for node in nodes:
          key = node[0].value
          val = node[1]
          if isinstance(val, ruamel.yaml.nodes.MappingNode):
              if key not in nodes_dict:
                  nodes_dict[key] = {}
              nodes_dict[key].update(deep_merge_nodes(val.value))
          elif isinstance(val, ruamel.yaml.nodes.ScalarNode):
              nodes_dict[key] = val.value
      return [(ruamel.yaml.nodes.ScalarNode(tag="tag:yaml.org,2002:str", value=key), ruamel.yaml.nodes.ScalarNode(tag="tag:yaml.org,2002:str", value=value)) for key, value in nodes_dict.items()]

def deep_merge_nodes(nodes):
    result = {}
    for node in nodes:
        key, value = node
        if key in result:
            result[key] = deep_merge(result[key], value)
        else:
            result[key] = value
    return result

def deep_merge_nodes(nodes):
    result = {}
    for key, value in nodes:
        if key not in result:
            result[key] = []
        result[key].append(value)

    for key, values in result.items():
        if len(values) == 1:
            result[key] = values[0]
        elif len(values) > 1:
            result[key] = deep_merge_nodes(values)
        else:
            result[key] = {}

    return result

def deep_merge_nodes(nodes):
        seen = {}
        out = []
        for (key, value) in nodes:
            if key not in seen:
                seen[key] = value
                out.append((key, value))
            else:
                existing_value = seen[key]
                if isinstance(existing_value, ruamel.yaml.nodes.MappingNode):
                    merged_value = existing_value + value
                    seen[key] = merged_value
                    out.append((key, merged_value))
                else:
                    seen[key] = value
                    out.append((key, value))
        return out

