def deep_merge_nodes(nodes):
    merged_nodes = {}
    for node in nodes:
        key, value = node
        if key in merged_nodes:
            current_value = merged_nodes[key]
            if not isinstance(current_value, ruamel.yaml.nodes.MappingNode):
                raise ValueError("Duplicate value for key '{}' with non-MappingNode non-overriding value of type {}".format(key, type(current_value).__name__))
            updated_value = {**current_value, **value}
            merged_nodes[key] = updated_value
        else:
            merged_nodes[key] = value
    return [
        (key, value) for key, value in merged_nodes.items()
    ]

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    """

    merged_nodes = []
    for node in nodes:
        key, value = node
        if isinstance(value, ruamel.yaml.nodes.MappingNode):
            for child in value.value:
                child_key, child_value = child
                if not isinstance(child_value, ruamel.yaml.nodes.MappingNode):
                    continue
                child_index = 0
                for merged_child in merged_nodes:
                    if child_key == merged_child[0]:
                        break
                    child_index += 1
                else:
                    child_node = (child_key, value)
                    merged_nodes.append(child_node)

        merged_nodes.append((key, value))

    return merged_nodes

def deep_merge_nodes(nodes):
    merged_nodes = {}
    for node in nodes:
        key, value = node
        if key not in merged_nodes:
            merged_nodes[key] = value
        else:
            merged_value = merged_nodes[key]
            if isinstance(merged_value, ruamel.yaml.nodes.MappingNode) and isinstance(value, ruamel.yaml.nodes.MappingNode):
                merged_nodes[key] = deep_merge_nodes({**merged_value.value, **value.value})
            else:
                merged_nodes[key] = value
    return list(merged_nodes.items())

