    # Iterate over each subparser in the dictionary
    for subparser_name, subparser in subparsers.items():
        # Try to parse the arguments using the current subparser
        try:
            # Get the parsed arguments for the current subparser
            parsed_arguments[subparser_name] = subparser.parse_args(unparsed_arguments)
            # Get the remaining arguments for the current subparser
            remaining_arguments = subparser.parse_known_args(unparsed_arguments)[1]
        # If the parsing is not successful, continue to the next subparser
        except SystemExit:
            continue
        # If the parsing is successful, break the loop
        else:
            break
    # Return the parsed arguments and remaining arguments as a tuple
    return (parsed_arguments, remaining_arguments)

