    for subcommand, subparser_info in SUBCOMMANDS.items():
        subparser = subparsers.add_parser(subcommand, help=subparser_info['help'])
        for option, option_info in subparser_info['options'].items():
            flag = '--' + option_info['long'] if 'long' in option_info else '-' + option_info['short']
            if option_info['type'] == bool:
                subparser.add_argument(flag, action='store_true', help=option_info['help'])
