    return parser, subparsers

def paging(response, max_results):
    if not isinstance(response, List):
        raise TypeError("response must be a list")
    if not isinstance(max_results, int):
        raise TypeError("max_results must be an integer")
    if max_results < 1:
        raise ValueError("max_results must be a positive integer")

    existing_objs = 0
    page_size = max_results
    for obj in response:
        existing_objs += 1
        if existing_objs == page_size:
            yield response[: page_size]
            response = response[page_size:]
            existing_objs = 0
    if existing_objs > 0:
        yield response[: existing_objs]

def paging(response, max_results):
    for i in range(0, len(response), max_results):
        yield response[i:i + max_results]

def size_to_bytes(size: str) -> int:
    units = {"K": 1000, "M": 1000000, "G": 1000000000}
    if not size:
        return 0
    if size.isdigit():
        return int(size)
    unit = size[-1]
    if unit in units:
        return int(size[:-1]) * units[unit]
    return 0

def size_to_bytes(size: str) -> int:
