    pattern = r"^[0-9]+[A-Z]{0,1}$"
    if not re.match(pattern, size):
        raise ValueError("Invalid file size")

    if size.endswith("K"):
        return int(size[:-1]) * 1000
    elif size.endswith("M"):
        return int(size[:-1]) * 1000000
    elif size.endswith("G"):
        return int(size[:-1]) * 1000000000
    elif size.endswith("T"):
        return int(size[:-1]) * 1000000000000
    else:
        return int(size)

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

    Examples:
        >>> size_to_bytes("500")
        500
        >>> size_to_bytes("1K")
        1000
    """
    if size.isdigit():
        return int(size)
    size = size.upper()
    if size.endswith("B"):
        return int(size[:-1])
    if size.endswith("KB"):
        return int(size[:-2]) * 1000
    if size.endswith("MB"):
        return int(size[:-2]) * 1000000
    if size.endswith("GB"):
        return int(size[:-2]) * 1000000000
    if size.endswith("TB"):
        return int(size[:-2]) * 1000000000000
    raise ValueError("Invalid input size")

def size_to_bytes(size):
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size (str): A string representing a human readable file size (eg: '500K')

    Returns:
        (int): A decimal representation of file size
    """
    size_suffixes = ['B', 'K', 'M', 'G', 'T', 'P', 'E', 'Z', 'Y']

    for suffix in size_suffixes:
        if size.lower().endswith(suffix):
            stripped_size = size[:-len(suffix)]
            if not stripped_size.isdigit():
                raise ValueError(f"Could not parse file size from '{size}'")
            return int(float(stripped_size) * (1024 ** size_suffixes.index(suffix)))

    if size.isdigit():
        return int(size)

    raise ValueError(f"Could not parse file size from '{size}'")

