def int_to_string(number, alphabet, padding=None):
    if not isinstance(number, int):
        raise TypeError("'number' must be an integer")
    if not isinstance(alphabet, list):
        raise TypeError("'alphabet' must be a list")
    if padding is not None and not isinstance(padding, int):
        raise TypeError("'padding' must be an integer or None")

    if number == 0:
        return alphabet[0]

    output = ''
    while number > 0:
        output = alphabet[number % len(alphabet)] + output
        number //= len(alphabet)

    if padding:
        while len(output) < padding:
            output = alphabet[0] + output

    return output

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int):
        raise ValueError("number must be an integer")
    if not isinstance(alphabet, list):
        raise ValueError("alphabet must be a list")
    if padding is not None and not isinstance(padding, int):
        raise ValueError("padding must be an integer or None")

    if number == 0:
        return "0"

    result = ""
    while number > 0:
        result = alphabet[number % len(alphabet)] + result
        number //= len(alphabet)

    if padding is not None and padding > len(result):
        result = result.zfill(padding)

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int):
        raise ValueError("number must be an integer")
    if not isinstance(alphabet, list):
        raise ValueError("alphabet must be a list")
    if padding is not None and not isinstance(padding, int):
        raise ValueError("padding must be an integer or None")

    if padding is not None and padding < 0:
        raise ValueError("padding must be a non-negative integer or None")

    if number == 0:
        return "0"

    output = ""
    while number > 0:
        remainder = number % len(alphabet)
        output = alphabet[remainder] + output
        number //= len(alphabet)

    if padding is not None and len(output) > padding:
        raise ValueError(f"number {number} cannot be converted to a string with padding {padding}")

    if padding is not None and len(output) < padding:
        output = "0" * (padding - len(output)) + output

    return output

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    str_rep = ''
    alphabet_size = len(alphabet)

    while number > 0:
        digit = number % alphabet_size
        str_rep = alphabet[digit] + str_rep
        number //= alphabet_size

    if padding is not None:
        str_rep = str_rep.zfill(padding)

    return str_rep

