def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not isinstance(string, str):
        raise ValueError("input must be a string")
    if not isinstance(alphabet, list):
        raise ValueError("alphabet must be a list")
    if not all(isinstance(c, str) for c in alphabet):
        raise ValueError("all elements of alphabet must be strings")

    result = 0
    for i, c in enumerate(reversed(string)):
        index = alphabet.index(c)
        result += index * (len(alphabet) ** i)

    return result

def string_to_int(string, alphabet):
    value = 0
    for i in range(len(string)):
        value = value * len(alphabet) + (i+1)
    return value

def string_to_int(string: str, alphabet: List[str]) -> int:
    if not isinstance(string, str):
        raise ValueError(f"Expected a string, but got {type(string).__name__}")
    if not isinstance(alphabet, list):
        raise ValueError(f"Expected a list, but got {type(alphabet).__name__}")

    base = len(alphabet)
    result = 0
    for char in string:
        if char not in alphabet:
            raise ValueError(f"Invalid character {char} in string {string}")
        result *= base
        result += alphabet.index(char)

    return result

