def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """

    if not frequency:
        return None
    if frequency == "always":
        return None

    freq_parts = frequency.split()
    num = int(freq_parts[0])
    unit = freq_parts[1].lower()

    if unit == "hour":
        return datetime.timedelta(hours=num)
    elif unit == "day":
        return datetime.timedelta(days=num)
    elif unit == "week":
        return datetime.timedelta(weeks=num)
    elif unit == "month":
        return datetime.timedelta(days=num * 30)
    elif unit == "year":
        return datetime.timedelta(days=num * 365)

    raise ValueError(f"Invalid frequency string: '{frequency}'")

def parse_frequency(frequency):
    if not frequency:
        return None
    if frequency.lower() == "always":
        return None
    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError("Invalid frequency string: " + frequency)
    number = parts[0]
    unit = parts[1].lower()
    if unit not in ["seconds", "minutes", "hours", "days", "weeks", "months", "years"]:
        raise ValueError("Invalid frequency unit: " + unit)
    return datetime.timedelta(**{unit: int(number)})

def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if not frequency:
        return None
    elif frequency.lower() == "always":
        return None
    else:
        frequency = frequency.lower()
        num, unit = frequency.split(maxsplit=1)
        try:
            num = int(num)
        except ValueError:
            raise ValueError(f"Expected a positive integer, but got {frequency}")
        if unit in ("weeks", "w"):
            return datetime.timedelta(weeks=num)
        elif unit in ("days", "d"):
            return datetime.timedelta(days=num)
        elif unit in ("hours", "hrs", "h"):
            return datetime.timedelta(hours=num)
        elif unit in ("minutes", "mins", "m"):
            return datetime.timedelta(minutes=num)
        elif unit in ("seconds", "secs", "s"):
            return datetime.timedelta(seconds=num)
        else:
            raise ValueError(f"Invalid unit {unit}: expected weeks, days, hours, minutes, or seconds.")

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    # Split the frequency string into its number and unit of time components
    parts = frequency.split(" ")
    # Convert the number to an integer
    number = int(parts[0])
    # Convert the unit of time to a timedelta class attribute (e.g. "years" => "year")
    unit = parts[1][:-1]
    return datetime.timedelta(**{unit: number})

