    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:

    """

    parsed_href = urllib.parse.urlparse(image_href)
    if parsed_href.scheme == "https":
        use_ssl = True
    elif parsed_href.scheme == "http":
        use_ssl = False
    else:
        raise ValueError("Unsupported image reference: %s" % image_href)

    return (parsed_href.path.strip("/"), parsed_href.netloc, use_ssl)

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    Raises:
        ValueError: if the format is invalid

    """
    if not image_href.startswith('http'):
        raise ValueError("Invalid image_href format")

    scheme, netloc, *path = urllib.parse(image_href)
    if not scheme or not netloc:
        raise ValueError("Invalid image_href format")

    image_id = None
    if scheme == 'http' and netloc == 'example.com':
        image_id = path[0][1:]
    elif scheme == 'https' and netloc == 'example.com':
        image_id = path[0][1:]
    else:
        raise ValueError("Invalid image_href format")

    use_ssl = True if scheme == 'http' else False
    return image_id, netloc, use_ssl

