def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        commands = [commands]

    # Verify that all commands are valid
    for command in commands:
        if not shutil.which(command):
            raise ValueError(f"Error: unable to find command '{command}' on the PATH.")

    # Build the command and options
    cmd = []
    if args:
        cmd.append(args)
    cmd.extend(commands)

    # Call the command
    if verbose:
        print(f"Running command: {cmd}")
    process = subprocess.Popen(cmd, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL if hide_stderr else None)
    process.wait()
    if process.returncode != 0:
        raise RuntimeError(f"Error: command '{cmd}' exited with non-zero exit status {process.returncode}")

