def find_roots(graph: rdflib.Graph, prop: rdflib.URIRef, roots: Optional[Set[rdflib.Node]] = None) -> Set[rdflib.Node]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    if roots is None:
        roots = set()

    for parent, _, child in graph.triples((None, prop, None)):
        if child not in graph:
            continue
        if parent not in graph:
            roots.add(child)
            continue
        if child not in roots:
            roots.add(child)
            find_roots(graph, prop, roots)

    return roots

def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    if not isinstance(graph, rdflib.Graph):
        raise TypeError("Invalid parameter 'graph'")
    if not isinstance(prop, rdflib.URIRef):
        raise TypeError("Invalid parameter 'prop'")
    if roots is not None and not isinstance(roots, set):
        raise TypeError("Invalid parameter 'roots'")

    if roots is None:
        roots = set()

    for s, _, o in graph.triples((None, prop, None)):
        if s not in roots and o not in roots:
            roots.add(s)

    return roots

def find_roots(graph: rdflib.Graph, prop: rdflib.URIRef, roots: Optional[Set[rdflib.Node]] = None) -> Set[rdflib.Node]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if not roots:
        roots = set()
    seen = set()
    for parent in graph.subjects(prop=prop):
        if parent not in seen:
            seen.add(parent)
            if not graph.objects(subject=parent, prop=prop):
                roots.add(parent)
            else:
                find_roots(graph, prop, roots)
    return roots

