    return (1 / (np.sqrt(2 * np.pi) * 0.1)) * np.exp(-((x - 0.2) ** 2) / (2 * 0.1 ** 2))

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    return np.exp(-((x - 0.2) ** 2) / (2 * (0.1 ** 2)))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    configs = {}
    parse_errors = []
    for config_filename in config_filenames:
        try:
            config_file = open(config_filename, "r")
            config = yaml.load(config_file, yaml.FullLoader)
            if resolve_env:
                config = dotenv.resolve(config)
            if overrides:
                config = dacite.merge(config, overrides)
            configs[config_filename] = config
        except Exception as e:
            parse_errors.append(logging.LogRecord(logging.ERROR, "Error parsing configuration file " + config_filename + ": " + str(e)))
    return configs, parse_errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """Given a sequence of configuration filenames, load and validate each configuration file. Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration, and sequence of logging.LogRecord instances containing any parse errors."""
    configs = {}
    logs = []

    for config_filename in config_filenames:
        try:
            config_file = open(config_filename)
            config = json.load(config_file)
            config_file.close()
            configs[config_filename] = config
        except Exception as e:
            logs.append(logging.LogRecord('load_configurations', logging.ERROR, errno.ENOENT, "No such file or directory: '{}'".format(config_filename)))

    if overrides:
        for config_filename, config in configs.items():
            for override_key, override_value in overrides.items():
                if override_key in config:
                    if resolve_env and isinstance(override_value, str) and '$' in override_value:
                        override_value = os.environ[override_value[1:]]
                    config[override_key] = override_value

    return configs, logs

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    configs = {}
    log_records = []
    for config_filename in config_filenames:
        try:
            with open(config_filename, 'r') as f:
                config = json.load(f)
        except FileNotFoundError:
            log_records.append(logging.LogRecord('CONFIG_LOAD_FAILED', 'Configuration file {} does not exist.'.format(config_filename)))
            continue
        except json.JSONDecodeError:
            log_records.append(logging.LogRecord('CONFIG_PARSE_ERROR', 'Configuration file {} is not valid JSON.'.format(config_filename)))
            continue
        else:
            if overrides:
                config = recursive_override(config, overrides)
            if resolve_env:
                config = resolve_env_vars(config)
            configs[config_filename] = config
    return configs, log_records

