def from_ticks(ticks, tz=None):
    cls = super().__class__
    tz = tz or datetime.timezone.utc
    if not 0 <= ticks < 86400000000000:
        raise ValueError("Ticks must be between 0 and 86400000000000")
    seconds, nanoseconds = divmod(ticks, 1000*1000*1000)
    microseconds = nanoseconds // 1000
    dt = datetime.datetime(2001, 1, 1, 0, 0, 0, tzinfo=tz)
    dt += datetime.timedelta(seconds=seconds, microseconds=microseconds)
    return cls(dt, tz)

def from_ticks(cls, ticks, tz=None):
    if not (0 <= ticks < 86400000000000):
        raise ValueError("ticks must be between 0 and 86400000000000 inclusive")
    return cls(ticks, tz)

def from_ticks(cls, ticks, tz=None):
    if ticks < 0 or ticks >= 86400000000000:
        raise ValueError("ticks must be between 0 and 86400000000000")
    if tz is not None and not isinstance(tz, datetime.tzinfo):
        raise ValueError("tz must be a datetime.tzinfo object")

    return cls(datetime.time(), hours=ticks // 3600000000, minutes=(ticks % 3600000000) // 60000000, seconds=(ticks % 60000000) // 1000000, microseconds=(ticks % 1000000) * 1000, tzinfo=tz)

def from_ticks(cls, ticks, tz=None):
    if 0 <= ticks < 86400000000000:
        return cls(ticks, tz=tz)
    else:
        raise ValueError("Ticks out of bounds (0 <= ticks < 86400000000000)")

def protocol_handlers(cls, protocol_version=None):
    if protocol_version is None:
        protocol_version = [(i.major, i.minor) for i in reversed(range(1, 6)) if (i.major, i.minor) in cls.Handler]
    if not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version is not a tuple")
    if protocol_version not in cls.Handler.keys():
        return {}
    return {i.major: i.minor for i in cls.Handler[protocol_version]}

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """

    if not isinstance(protocol_version, tuple):
        raise TypeError(f"Protocol version must be a tuple, not {type(protocol_version)}.")

    if protocol_version:
        if cls._protocol_handlers.get(protocol_version) is None:
            raise ValueError(f"Unknown protocol version {protocol_version}.")
        return {protocol_version: cls._protocol_handlers[protocol_version]}
    else:
        return {version: cls._protocol_handlers[version] for version in cls._protocol_handlers}

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None and type(protocol_version) != tuple:
            raise TypeError("protocol version must be a tuple")

        if protocol_version is None:
            return {k: v for k, v in cls.SUPPORTED_PROTOCOLS.items() if kwargs.get(k)}
        else:
            return {protocol_version: cls.SUPPORTED_PROTOCOLS.get(protocol_version, None)}

def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers, keyed by version tuple. If an explicit protocol version is provided, the dictionary will contain either zero or one items, depending on whether that version is supported. If no protocol version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is None:
        return {(p, m): cls.handler for p in cls.protocol_versions for m in cls.message_types(p)}
    elif isinstance(protocol_version, tuple):
        if protocol_version not in cls.protocol_versions:
            raise TypeError("unknown protocol version " + str(protocol_version))
        else:
            return {protocol_version: cls.handler()}
    else:
        raise TypeError("protocol version is not passed in a tuple")

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.

    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, str):
        return seq, str
    else:
        with io.BufferedReader(seq, bufsize) as buf:
            return seq, type(buf.read(1)[0])

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, str):
        return (seq, str)
    elif isinstance(seq, bytes):
        return (seq, bytes)
    elif isinstance(seq, bytearray):
        return (seq, bytearray)
    elif isinstance(seq, memoryview):
        return (seq, type(seq))
    elif isinstance(seq, list):
        return (seq, list)
    elif isinstance(seq, tuple):
        return (seq, tuple)
    elif isinstance(seq, range):
        return (seq, range)
    elif isinstance(seq, slice):
        return (seq, slice)
    elif isinstance(seq, Iterable):
        return (list(seq), list)
    else:
        raise TypeError("Invalid argument type")

def _get_seq_with_type(seq, bufsize=None):
    if isinstance(seq, str):
        return (seq, str)
    elif hasattr(seq, "__next__"):
        return (seq, type(next(iter(seq))))
    else:
        raise ValueError("seq must be a string or a sequence")

def _get_seq_with_type(seq, bufsize=None):
    if isinstance(seq, str):
        return seq, str
    if isinstance(seq, bytes):
        return seq, bytes

    if hasattr(seq, "__bufsize__"):
        buffer = seq.__bufsize__
    else:
        buffer = getDefaultBufferSize(bufsize)

    if hasattr(seq, "read"):
        if buffer < 0:
            raise ValueError("buffer size must be >= 0")
        if hasattr(seq, "end_of_stream"):
            if buffer == 0 and not seq.end_of_stream:
                raise ValueError("expected end_of_stream")
        else:
            if buffer == 0 and not seq.tell() == seq.size:
                raise ValueError("expected end_of_stream")

    buffer_type = type(buffer)
    if buffer_type == int:
        if buffer < 0:
            raise ValueError("buffer size must be >= 0")

    return seq, buffer_type

def scale(self, other=None, recompute=False):
    if not self.scale or recompute:
        self.scale = compute_scale(self)
    if other is not None:
        assert isinstance(other, (int, float))
        if self.scale == 0:
            raise LenaValueError("Can't rescale a histogram with scale equal to zero.")
        for (count, _) in enumerate(self.bins):
            self.bins[count] = other*self.bins[count]/self.scale
        self.scale = other
    return self.scale

def scale(self, other=None, recompute=False):
    if other is None:
        if not hasattr(self, "scale_") or self.scale_ is None or recompute:
            self.scale_ = current_scale = sum(self)
        return self.scale_
    else:
        if self.scale_ == 0:
            raise LenaValueError("Can't rescale histogram with scale equal to zero.")
        else:
            for x, y in enumerate(self):
                self[x] *= other * current_scale / self.scale_
            self.scale_ = other * current_scale

def scale(self, other=None):
    if other is None:
        return self.scale
    elif isinstance(other, (int, float)):
        if self.scale == 0 or self.scale is None:
            raise LenaValueError("Unknown or zero scale, cannot rescale.")

        self.scale = other
        for field, fieldvalues in self.fields.items():
            if field.endswith("_error"):
                self.fields[field] = (fieldvalues[0] / self.scale) * other
    else:
        raise TypeError("Expected None or numeric value, got {0}".format(type(other).__name__))

def scale(self, other=None):
    if other is None:
        return self.scale
    elif isinstance(other, (int, float)):
        if self.scale == 0:
            raise LenaValueError("Cannot rescale graph with unknown scale")
        self.scale = other
        for elem in self.errors:
            elem.scale(other)
        for edge in self.edges:
            edge.scale(other)
    else:
        raise LenaTypeError("Scale must be numeric")

def scale(self, other=None):
    if other is None:
        return self._scale
    elif isinstance(other, numbers.Number):
        # Rescale to the provided value
        scale = other
        # Rescale all elements in the graph
        for el in self:
            # Rescale the last coordinate
            if len(el.geometry) > 1:
                el.geometry[-1] = el.geometry[-1] * scale
        self._scale = scale
    else:
        raise TypeError("'other' must be either None or a number")

def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if not isinstance(hist, Histogram):
        raise TypeError("hist must be a Histogram object")
    if not callable(make_value) and make_value is not None:
        raise TypeError("make_value must be either None or callable")
    if get_coordinate not in ("left", "middle", "right"):
        raise ValueError("get_coordinate must be either 'left', 'middle' or 'right'")
    if scale not in (None, True):
        raise ValueError("scale must be either None or True")
    if not isinstance(field_names, (list, tuple)):
        raise TypeError("field_names must be a list or tuple")
    if len(field_names) != hist.dimension:
        raise ValueError(f"length of field_names must be {hist.dimension}")

    if scale is None:
        scale = hist.scale
    graph = Graph()

    i = 0
    while (i + 1) * hist.bin_width < hist.size[0]:
        x = i * hist.bin_width
        if get_coordinate == "left":
            x += hist.bin_width / 2
        elif get_coordinate == "right":
            x -= hist.bin_width / 2
        bins = hist.get_bins(x, i * hist.bin_width)
        if not bins:
            raise ValueError("hist contains only empty bins")
        bin_coord = bins[0][get_coordinate]
        value = None
        if make_value is not None:
            value = make_value(bins[0])
        for field_name, bin_value in zip(field_names, value):
            graph.add_point(bin_coord, bin_value, field_name)
        i += 1
    return graph

def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    # Initialize a new graph with the same dimension as the histogram
    graph = Graph(len(hist.bins))

    # Iterate over the bins of the histogram
    for i, bin_ in enumerate(hist.bins):
        # Get the coordinate of the graph point
        if get_coordinate == "left":
            coord = bin_.left
        elif get_coordinate == "right":
            coord = bin_.right
        else:
            coord = (bin_.left + bin_.right) / 2

        # Set the value of the graph point
        if make_value is None:
            value = bin_.content
        else:
            value = make_value(bin_)

        # Set the scale of the graph point
        if scale is None:
            scale = hist.scale

        graph.add_point(coord, value, scale)

    # Set the field names of the graph
    graph.field_names = field_names

    # Return the resulting graph
    return graph

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_

    if get_coordinate == "left":
        get_coordinate = lambda bin_: bin_.low
    elif get_coordinate == "right":
        get_coordinate = lambda bin_: bin_.high
    elif get_coordinate == "middle":
        get_coordinate = lambda bin_: (bin_.low + bin_.high) / 2
    else:
        raise ValueError("Unknown coordinate")

    if field_names == "x":
        field_names = ("x",)
    elif field_names == "y":
        field_names = ("y",)
    else:
        field_names = ("x", "y")

    result = []
    for bin_ in hist:
        point = {}
        for name in field_names:
            if name == "x":
                point[name] = get_coordinate(bin_)
            else:
                point[name] = make_value(bin_)[name]
        result.append(point)

    if scale is True:
        scale = hist.scale
    elif scale is None:
        scale = (0, hist.bins)
    else:
        scale = tuple(scale)

    return Graph(result, scale=scale)

def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if not isinstance(hist, Histogram):
        raise TypeError("hist must be a Histogram")
    if make_value is None:
        def make_value(bin_):
            return bin_.content
    if not callable(make_value):
        raise TypeError("make_value must be callable")
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be either 'left', 'right' or 'middle'")
    if len(field_names) != hist.ndim:
        raise ValueError("field_names must have the same number of elements as hist's dimension")
    if scale is not None and not isinstance(scale, Scale):
        raise TypeError("scale must be None or a Scale")
    return Graph(
        bins=[GraphPoint(field_names[i], make_value(bin_)) for i, bin_ in enumerate(hist)],
        scale=scale or hist.scale,
    )

def _verify(iface, candidate, tentative=False, vtype=None):
    provided_by_candidate = iface.providedBy(candidate)
    if not provided_by_candidate and not tentative:
        raise zope.interface.Invalid(
            "Candidate does not declare that it provides the interface"
        )

    necessary_attributes = iface.getAttributes()
    for attribute in necessary_attributes:
        if attribute.name not in candidate:
            raise zope.interface.Invalid(
                "Attribute %s is missing from %s" % (attribute.name, candidate)
            )

    necessary_methods = iface.getMethods()
    for method in necessary_methods:
        if method.name not in candidate:
            raise zope.interface.Invalid(
                "Method %s is missing from %s" % (method.name, candidate)
            )
        else:
            candidate_method = getattr(candidate, method.name)
            if not all([p.annotation.type in candidate_method.parameters for p in method.parameters]):
                raise zope.interface.Invalid(
                    "Parameter types do not match for method %s on %s" % (method.name, candidate)
                )
            if method.result.type != candidate_method.return_type:
                raise zope.interface.Invalid(
                    "Return type does not match for method %s on %s" % (method.name, candidate)
                )

    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative:
        if not iface.providedBy(candidate):
            return False
    for name, method in iface.namesAndMethods():
        if not hasattr(candidate, name):
            return False
        candidate_method = getattr(candidate, name)
        try:
            method.verifySignature(candidate_method)
        except ValidationError:
            return False
    for name, attribute in iface.namesAndAttributes():
        if not hasattr(candidate, name):
            return False
        candidate_attribute = getattr(candidate, name)
        if not attribute.validate(candidate_attribute):
            return False
    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the interface using
      `iface.providedBy` (unless `tentative` is `True`, in which case this step is skipped).
      This means that the candidate's class declares that it `implements <zope.interface.implementer>`
      the interface, or the candidate itself declares that it `provides <zope.interface.provider>` the interface
    - Making sure the candidate defines all the necessary methods
    - Making sure the methods have the correct signature (to the extent possible)
    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be checked passed.
    :raises zope.interface.Invalid: If any of the previous conditions does not hold."""

    if not tentative:
        if not iface.providedBy(candidate):
            # This will only happen if the interface looks like this: `provide(object)`
            raise Invalid(f"{candidate} does not provide {iface}")

    iface = iface.resolve()

    if not tentative and not isinstance(candidate, iface):
        # If the interface restriction was not given, but the type in the
        # definition was, check it here!
        raise Invalid(f"{candidate} does not implement {iface}")

    try:
        implementors = candidate.get_implementors()
    except AttributeError:
        implementors = ()

    for implem_iface in implementors:
        if not implem_iface.is_based_on(iface):
            raise Invalid(f"Invalid implementor {implem_iface} for {candidate}")

    for name in iface.names():
        # Get the normalized method name
        im_name = iface.get(name).get_vmethod_name()

        # Check if the candidate provides this method
        try:
            imp_name = candidate.get_implemented_methods()[im_name]
        except KeyError:
            raise Invalid(f"Method {im_name} is not implemented by {candidate}")

        # Now check if the method has the expected signature
        sig = iface.get(name).signature()
        if sig:
            imp_sig = candidate.get_implemented_methods()[im_name].signature
            if sig != imp_sig:
                raise Invalid(f"Signature of method {im_name} mismatch (expected={sig}, actual={imp_sig})")

    attributes = {attr.normalized_name for attr in iface.directly_provided()}

    for name in attributes:
        try:
            candidate.get_implemented_attribute(name)
        except AttributeError:
            raise Invalid(f"Attribute {name} is not implemented by {candidate}")

    return True

def _verify(iface, candidate):
    # Check if the candidate claims to provide the interface
    if not iface.providedBy(candidate):
        raise zope.interface.Invalid(f"{candidate} does not claim to provide interface {iface}")

    # Check if the candidate defines all the necessary methods
    for meth in iface.names('methods'):
        if not hasattr(candidate, meth):
            raise zope.interface.Invalid(f"{candidate} does not define method {meth}")

    # Check if the methods have the correct signature
    for meth in iface.names('methods'):
        candidate_sig = inspect.signature(candidate.__dict__[meth])
        iface_sig = iface.get(meth).signature
        if candidate_sig != iface_sig:
            raise zope.interface.Invalid(f"Incorrect signature for method {meth} in {candidate}: expected {iface_sig}, got {candidate_sig}")

    # Check if the candidate defines all the necessary attributes
    for attr in iface.names('properties'):
        if not hasattr(candidate, attr):
            raise zope.interface.Invalid(f"{candidate} does not define attribute {attr}")

    # If everything checks out, return True
    return True

def verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.
    """

    if not tentative:
        if not iface.providedBy(candidate):
            raise zope.interface.Invalid(candidate, iface)

    mapping = {
        'methods': {
            'mandatory': iface.namesAndAllInterfaces(),
            'optional': (),
        },
        'attributes': {
            'mandatory': iface.namesAndAllInterfaces(),
            'optional': ()
        }
    }

    for name, type_ in mapping['methods']['mandatory']:
        try:
            candidate_method = getattr(candidate, name)
        except AttributeError:
            raise zope.interface.Invalid(candidate, iface)
        else:
            try:
                candidate_method.required_interface
            except AttributeError:
                pass
            else:
                if not candidate_method.required_interface.providedBy(candidate_method):
                    raise zope.interface.Invalid(candidate, iface)

    for name, type_ in mapping['attributes']['mandatory']:
        try:
            candidate_attr = getattr(candidate, name)
        except AttributeError:
            raise zope.interface.Invalid(candidate, iface)

    return True

