def determineMetaclass(bases, explicit_mc=None):
    # Return metaclass for a class with the given bases and optional explicit metaclass
    # bases can be a tuple of base classes or a single base class
    # explicit_mc is the __metaclass__ attribute of the class
    # If there's no explicit_mc, then we try to get it from the first base

    # Use the first base's metaclass as the default
    if isinstance(bases, tuple):
        mc = bases[0].__class__
        for base in bases:
            if base.__class__ != mc:
                raise InvalidMetaclassError("Mixing metaclasses is not allowed")
    else:
        mc = bases.__class__

    # If there's an explicit metaclass, use it instead of the default
    # if it's a type() or a callable in the form of a class
    if explicit_mc:
        if isinstance(explicit_mc, type):
            mc = explicit_mc
        elif callable(explicit_mc):
            mc = explicit_mc
        else:
            raise InvalidMetaclassError("Invalid explicit metaclass: {}".format(explicit_mc))

    return mc

