        for base in bases:
            if not issubclass(explicit_mc, base.__metaclass__):
                raise TypeError("Explicit metaclass %s is not a subclass of %s" % (explicit_mc, base.__metaclass__))
        return explicit_mc
    else:
        # If no explicit metaclass is given, use the first base's metaclass
        return bases[0].__metaclass__

