    for key, value in kwargs.items():
        if key not in ["fuzzy_with_tokens", "target"]:
            parser_kwargs[key] = value

    parser = CParser(**parser_kwargs)
    tokens, time_tuple, tz_info = parser.parse(timestr, default=default, ignoretz=ignoretz, tzinfos=tzinfos)

    if not time_tuple:
        return None

    date = datetime.datetime(*time_tuple)

    if tz_info is not None and hasattr(date, "tzinfo"):
