def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    start_code_block = False
    end_code_block = False
    for i, char in enumerate(text):
        if char == "<" and text[i+1] == "%":
            start_code_block = True
        elif char == "%" and text[i-1] == "<":
            end_code_block = True
        elif char == "%" and text[i-1] == ">":
            end_code_block = True
        elif (not start_code_block) and (not end_code_block):
            tags.add(char)
        if start_code_block and char == "%":
            start_code_block = False
        if end_code_block and char == "%":
            end_code_block = False
    if replacer:
        replaced_text = replacer(text)
    else:
        replaced_text = text
    return tags, replaced_text

def find_tags(text, replacer=None):
    tags = set()
    pattern = r"<[^>]+>"
    for match in re.finditer(pattern, text):
        tag = match.group(0)
        tags.add(tag)
        if replacer:
            text = text.replace(tag, replacer(tag))
    return tags, text

def process_text_links(text):
    matches = re.finditer(r"\[.+?\]", text)
    for match in matches:
        link = match.group()[1:-1]
        text = text.replace(link, f"<a href='{link}'>{link}</a>")
    return text

def process_text_links(text):
    links = []
    for match in re.finditer(r"\[[^\]]*\]\([^)]*\)", text):
        link = match.group(0)
        if ")" in link and "(" in link:
            links.append(link[link.find("(") + 1:link.find(")")])
        elif ">" in link and "<" in link:
            links.append(link[link.find(">") + 1:link.find("<")])
        elif "." in link and "," in link:
            links.append(link[link.find(".") + 1:link.find(",")])
        else:
            links.append(link)
    for link in links:
        if not re.match("https://", link) and not re.match("http://", link):
            link = "http://" + link
        text = re.sub(r"\[" + link + "\]", "<a href=\"" + link + "\">" + link + "</a>", text, 1)
    return text

def process_text_links(text):
    # Check if input text is none or empty
    if text in [None, '']:
        return text

    # Extract all links from text
    links = re.findall(r'(http[s]?://(?:[a-zA-Z]|[0-9]|[$-_@.&+]|[!*\(\),]|(?:%[0-9a-fA-F][0-9a-fA-F]))+)', text)

    # Iterate over each link and add attributes
    for link in links:
        # Check if link is already linked
        if 'class="link"' not in link:
            # Replace link with linkified version
            text = text.replace(link, '<a class="link" href="' + link + '">' + link + '</a>')

    return text

