private static Dictionary<string, string> GetNodeinfoWellKnownDocument(string url, string documentPath = null)
{
    if (!Uri.IsWellFormedUriString(url, UriKind.Absolute))
    {
        throw new ArgumentException("Supplied URL is not well-formed", nameof(url));
    }

    if (string.IsNullOrWhiteSpace(documentPath))
    {
        documentPath = "/.well-known/nodeinfo";
    }

    if (!documentPath.StartsWith("/") || !documentPath.EndsWith("/"))
    {
        throw new ArgumentException("Supplied document path is not valid", nameof(documentPath));
    }

    var uri = new Uri(url);
    var getRequest = WebRequest.CreateHttp(Uri.EscapeUriString(uri.AbsoluteUri + documentPath));
    getRequest.Method = "GET";
    getRequest.Headers.Add(HttpRequestHeader.Accept, "application/json");

    var requestStream = getRequest.GetRequestStream();

    using (requestStream)
    {
        requestStream.Write(new byte[0], 0, 0);
    }

    var getResponse = (HttpWebResponse) getRequest.GetResponseAsync().Result;

    if (getResponse.StatusCode != HttpStatusCode.OK)
    {
        getResponse.Close();
        throw new ArgumentException($"Unable to access file at {url}{documentPath}");
    }

    var responseStream = getResponse.GetResponseStream();

    using (var reader = new StreamReader(responseStream))
    {
        var responseContent = reader.ReadToEnd();

        var nodeinfo = JsonConvert.DeserializeObject<Dictionary<string, string>>(responseContent);

        return nodeinfo;
    }
}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Edge cases to handle:
    # 1. The document does not contain the mandatory fields
    # 2. The document contains XRD in the <Link> tag
    # 3. The document contains JSON in the <Content> tag
    # 4. The JSON contains invalid data (e.g. non-string values for string keys)

    try:
        # If the document contains XRD in the <Link> tag
        if "<Link rel=\"http://axschema.org/foaf/name\"" in document and "<Link rel=\"http://axschema.org/foaf/image\"" in document:
            # Parse the XRD data and extract the required fields
            webfinger = {}
            for tag in ["foaf_name", "foaf_img"]:
                webfinger[tag] = re.findall(r"<Link rel=\"http://axschema.org/foaf/" + tag + "(.*?)<", document)[0]
            return webfinger
        # If the document contains JSON in the <Content> tag
        elif "<Content type=\"application/json\">" in document:
            # Parse the JSON data and extract the required fields
            webfinger = json.loads(document)
            required_fields = ["name", "image"]
            # Verify that the JSON contains the required fields
            for field in required_fields:
                if field not in webfinger:
                    raise Exception("Missing required field '{}'".format(field))
            return webfinger
        # If the document contains invalid data
        else:
            raise Exception("Invalid document")
    except Exception as e:
        # If an exception is raised during parsing, return an empty dictionary
        return {}

def parse_diaspora_webfinger(document: str) -> Dict:
    try:
        # if the documentation is in JSON format, parse it with the json module
        return json.loads(document)
    except json.JSONDecodeError:
        # if the documentation is in XRD format, parse it with the xml package
        xml_data = xml.etree.ElementTree.fromstring(document)
        # find the XML node that contains the relevant data
        webfinger_data = xml_data.find("{http://docs.oasis-open.org/ns/xri/xrd-2.0/atom#}Subject").text
        # convert the data to a dictionary
        return json.loads(webfinger_data)
    except (json.JSONDecodeError, xml.etree.ElementTree.ParseError):
        # if the parsing fails for any reason, raise an appropriate exception
        raise ValueError("Invalid Diaspora webfinger data")

