def insert_nested_value(dict_, value, *keys):
  """Insert a value of a nested key into a dictionary"""
  if len(keys) == 0:
    return value
  else:
    key = keys[0]
    subdict = {key: dict_.get(key, {})}
    subdict = insert_nested_value(subdict, value, *keys[1:])
    dict_[key] = subdict
    return dict_

