def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    # Check if the settings_dirs is a string or a list of strings
    if isinstance(settings_dirs, str):
        settings_dirs = [settings_dirs]
    if not isinstance(settings_dirs, list):
        raise TypeError("settings_dirs must be a string or a list of strings")

    # Check if spec_option is a string or a list of strings
    if isinstance(spec_option, str):
        spec_option = [spec_option]
    if not isinstance(spec_option, list):
        raise TypeError("spec_option must be a string or a list of strings")

    # Create a list to store the file names
    file_names = []

    # Iterate over the setting directories and add their file names to the list
    for settings_dir in settings_dirs:
        for root, dirs, files in os.walk(settings_dir):
            for file in files:
                if file.endswith(".ini"):
                    file_names.append(os.path.join(root, file))

    # Iterate over the spec options and add their file names to the list
    for spec_option in spec_option:
        file_names.append(os.path.join(spec_option, "settings.ini"))

    # Return the list of file names
    return file_names

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    ini_type = IniType(attrs={'element_attribs': {'name': ''}, 'complex_subs': {}})
    # Add name attribute to the parent element
    ini_type.attrib({'name': spec_option})
    # Add a list of names to the parent element
    for settings_dir in settings_dirs:
        # Create a new ComplexType element and add it to the IniType
        directory_type = ComplexType(
            attrs={
                'complex_content': {
                    'value': {
                        'name': settings_dir,
                        'inheritable': True
                    },
                    'base': settings_dir
                }
            }
        )
        ini_type.complex_content.append(directory_type)
        # Add a list of files to the ComplexType
        file_names = os.listdir(settings_dir)
        for file_name in file_names:
            file_type = ComplexType(
                attrs={
                    'complex_content': {
                        'value': file_name,
                        'inheritable': True
                    }
                }
            )
            directory_type.complex_content.append(file_type)
    return ini_type

