    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    if not yaml_file:
        raise ValueError("Must provide a YAML file to validate")

    try:
        with open(yaml_file, "r") as f:
            data = yaml.safe_load(f)
    except FileNotFoundError:
        raise ValueError(f"YAML file {yaml_file} not found")
    except YAMLError as ex:
        raise ValueError(f"Error loading YAML file {yaml_file}: {ex}")

    missing_keys = []
    for key in cls.REQUIRED_KEYS:
        if key not in data:
            missing_keys.append(key)

    if missing_keys:
        raise IRValidatorException(f"Mandatory keys {missing_keys} are missing in YAML file {yaml_file}")

    return data

