        extra_vars = {}

    if not ansible_args:
        ansible_args = {}

    # Configure playbook path and verbosity level
    ansible_args["playbook_path"] = playbook_path
    if verbose:
        ansible_args["verbose"] = verbose

    # Set extravars and args
    extra_vars.update(ansible_args)

    # Create temporary directory for storing playbook artifacts
    tmp_dir = Path(ir_workspace.path) / "ansible"
    if not tmp_dir.exists():
        tmp_dir.mkdir()

    # Run 'ansible-playbook' CLI with temporary directory and extravars
    args = [sys.executable, "-m", "ansible_playbook", "--directory", tmp_dir, "--extra-vars", json.dumps(extra_vars)]
    status = subprocess.call(args)

    if status != 0:
        raise subprocess.CalledProcessError(status, " ".join(args))

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """

    # Load the config, if a global one exists
    if self.config_file:
        self.config = self.load_config(parser_name)

    # Load the command-line parameters
    for param in self.params:
        cls = param.get("type")
        if cls is None:
            cls = str
        if param["name"] not in values_dict:
            continue
        try:
            values_dict[param["name"]] = cls(values_dict[param["name"]])
        except ValueError as e:
            raise ValueError(f"Error converting parameter '{param['name']}' to type '{cls.__name__}': {e}")

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """

    for key, value in values_dict.items():
        if parser_name in self.valid_args:
            if key in self.valid_args[parser_name]:
                if self.valid_args[parser_name][key]['type'] == 'boolean':
                    values_dict[key] = (value.lower() == 'true')
                elif self.valid_args[parser_name][key]['type'] == 'int':
                    values_dict[key] = int(value)
                elif self.valid_args[parser_name][key]['type'] == 'float':
                    values_dict[key] = float(value)
                elif self.valid_args[parser_name][key]['type'] == 'list':
                    values_dict[key] = value.split(',')
                elif self.valid_args[parser_name][key]['type'] == 'dict':
                    values_dict[key] = json.loads(value)
                elif self.valid_args[parser_name][key]['type'] == 'string':
                    values_dict[key] = str(value)
                else:
                    raise ValueError(f"Invalid type '{self.valid_args[parser_name][key]['type']}' specified for argument '{key}'")
            else:
                raise ValueError(f"Invalid argument '{key}' specified for command '{parser_name}'")
        else:
            raise ValueError(f"Invalid command '{parser_name}' specified")

def _convert_non_cli_args(self, parser_name, values_dict):
    for arg in values_dict:
        value = values_dict[arg]
        arg_type = self.argument_types[arg]
        if arg_type == "int":
            values_dict[arg] = int(value)
        elif arg_type == "float":
            values_dict[arg] = float(value)
        elif arg_type == "bool":
            values_dict[arg] = value.lower() in ["yes", "true", "1"]
        elif arg_type == "list":
            values_dict[arg] = value.split(",")
        elif arg_type == "dict":
            values_dict[arg] = eval(value)
        elif arg_type == "str":
            values_dict[arg] = value
        else:
            raise ValueError(f"Invalid argument type: {arg_type}")

def _convert_non_cli_args(self, parser_name, values_dict):
    if parser_name == "virsh":
