        values_dict["boot_from"] = self._convert_boot_from(values_dict["boot_from"])
        values_dict["remote"] = values_dict["remote"].lower() in ("true", "yes", "on", "1")
        values_dict["migrate_portal"] = values_dict["migrate_portal"].lower() in ("true", "yes", "on", "1")
    elif parser_name == "ospd":
