def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
"""
    assert isinstance(values_dict, dict)

    # Convert numeric args to int or float as appropriate
    for arg in config.get(parser_name, 'numeric_args', []):
        if arg in values_dict and values_dict[arg] != '':
            if config.get(parser_name, arg + '_is_int', False):
                values_dict[arg] = int(values_dict[arg])
            else:
                values_dict[arg] = float(values_dict[arg])

    # Convert boolean args to boolean
    for arg in config.get(parser_name, 'boolean_args', []):
        if arg in values_dict and values_dict[arg].lower() == 'true':
            values_dict[arg] = True
        elif arg in values_dict and values_dict[arg].lower() == 'false':
            values_dict[arg] = False

    # Convert list args to lists
    for arg in config.get(parser_name, 'list_args', []):
        if arg in values_dict:
            values_dict[arg] = values_dict[arg].split(",")

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    properties = {}
    for root, dirs, files in os.walk(plugin_dir):
        for file in files:
            if file.endswith(".spec"):
                with open(os.path.join(root, file)) as f:
                    spec_data = json.load(f)
                    properties[file] = spec_data
    return properties

